-- Misc MySQL-compatible statements seen in migration tools, monitoring agents and ORMs (Django, Rails, Laravel)
SELECT @@version_comment LIMIT 1;
SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA = 'shop' AND TABLE_NAME = 'users' LIMIT 1;
SELECT `users`.* FROM `users` WHERE `users`.`deleted_at` IS NULL ORDER BY `users`.`id` ASC LIMIT 1;
SELECT COUNT(*) AS `count` FROM `orders` WHERE `orders`.`user_id` = 5;
SELECT `orders`.`id` AS t0_r0, `users`.`id` AS t1_r0 FROM `orders` LEFT OUTER JOIN `users` ON `users`.`id` = `orders`.`user_id`;
SELECT 1 AS one FROM `users` WHERE `users`.`email` = BINARY 'a@b.c' LIMIT 1;
INSERT INTO `django_migrations` (`app`, `name`, `applied`) VALUES ('auth', '0001_initial', '2025-01-01 00:00:00.000000');
UPDATE `users` SET `last_login` = '2025-01-01 00:00:00.000000' WHERE `users`.`id` = 1;
DELETE FROM `django_session` WHERE `django_session`.`expire_date` < '2025-01-01 00:00:00.000000';
SELECT `a`.`id`, `a`.`title` FROM `articles` `a` WHERE `a`.`id` IN (1, 2, 3) AND `a`.`status` = 'published';
SELECT SQL_NO_CACHE * FROM t1;
SELECT DISTINCTROW a FROM t1;
SELECT HIGH_PRIORITY a FROM t1;
SELECT ALL a FROM t1;
SELECT a FROM t1 WHERE b = 'x' COLLATE utf8mb4_bin;
SELECT CURRENT_TIMESTAMP, CURRENT_DATE, CURRENT_TIME, LOCALTIME, NOW(6), UTC_TIMESTAMP();
SELECT EXTRACT(YEAR FROM created_at), EXTRACT(MONTH FROM created_at) FROM orders;
SELECT SUBSTRING(name FROM 2 FOR 3), POSITION('a' IN name), TRIM(LEADING '0' FROM code) FROM t;
SELECT CHAR_LENGTH(name), LENGTH(name), REVERSE(name), REPEAT('x', 3), REPLACE(name, 'a', 'b'), INSTR(name, 'a'), LOCATE('a', name) FROM t;
SELECT MD5(email), SHA1(email), SHA2(email, 256), HEX(name), UNHEX('41'), TO_BASE64(name), FROM_BASE64('QQ==') FROM users;
SELECT AES_ENCRYPT('x', 'k'), AES_DECRYPT(col, 'k'), COMPRESS(col), UNCOMPRESS(col) FROM t;
SELECT INET_ATON('1.2.3.4'), INET_NTOA(16909060), INET6_ATON('::1');
SELECT IFNULL(a, 0) + IFNULL(b, 0), NULLIF(a, 0), GREATEST(a, b, c), LEAST(a, b, c) FROM t;
SELECT GET_LOCK('k', 10), RELEASE_LOCK('k'), IS_FREE_LOCK('k');
SELECT SLEEP(1), BENCHMARK(1000, MD5('x')), CONNECTION_ID(), ROW_COUNT();
SELECT a FROM t1 WHERE a > 1 UNION DISTINCT SELECT a FROM t2;
SELECT a, b FROM t1 ORDER BY a ASC, b DESC LIMIT 3 OFFSET 2;
SELECT * FROM t1 WHERE a = 1 ORDER BY 1, 2;
SELECT t1.*, t2.* FROM t1, t2;
SELECT db1.t1.col FROM db1.t1;
SELECT `my table`.`my col` FROM `my table`;
SELECT * FROM t1 WHERE a = -1 AND b = - 1 AND c = +1;
SELECT 1 FROM t1 WHERE a IN (SELECT 1) AND b NOT BETWEEN 1 AND 2 AND c NOT LIKE 'x' AND d NOT IN (1, 2);
SELECT a FROM t1 WHERE a SOUNDS LIKE 'abc';
SELECT a FROM t1 WHERE a RLIKE '^x';
SELECT a FROM t1 WHERE NOT EXISTS (SELECT 1 FROM t2 WHERE t2.a = t1.a);
SELECT a FROM t1 WHERE a IS TRUE AND b IS NOT FALSE AND c IS UNKNOWN;
SELECT a & b, a | b, a ^ b, a << 1, a >> 1 FROM t1;
SHOW CREATE VIEW v_active_users;
SHOW TABLE STATUS LIKE 'orders';
SHOW ENGINE INNODB STATUS;
SHOW MASTER STATUS;
SHOW SLAVE STATUS;
SHOW WARNINGS;
SHOW ERRORS;
SHOW DATABASES;
SHOW FULL TABLES FROM shop WHERE Table_type = 'BASE TABLE';
SHOW BINARY LOGS;
SHOW CREATE SEQUENCE seq_invoice;
SHOW COLLATION LIKE 'utf8mb4%';
SHOW GLOBAL STATUS LIKE 'Questions';
EXPLAIN EXTENDED SELECT * FROM t1;
EXPLAIN SELECT * FROM t1 WHERE a = 1;
EXPLAIN DELETE FROM t1 WHERE a = 1;
ANALYZE SELECT * FROM t1 WHERE a = 1;
ANALYZE FORMAT=JSON SELECT * FROM t1;
